// ---- Workflow configuration: edit these values for your environment ----
const CONFIG = {
 api_base_url: "http://host.docker.internal:8000",   // Sentient AI matching service (sentient_api.py)
  confidence_threshold: 0.50,               // below this, the case goes to staff review
  staff_email: "referrals-staff@example.com",
  clinic_name: "Sentient AI Referral Clinic",
  timezone: "America/Chicago",
  default_appointment_time: "09:00",
  appointment_minutes: 30,
  calendar_id: "primary",                  // staff "Draft Referrals" calendar ID
};

const envelope = $input.first().json;
const input = envelope.body ?? envelope;
const str = (v) => (typeof v === "string" ? v.trim() : "");

const caseId = str(input.case_id);
const clinicalText = str(input.clinical_text ?? input.clinical_notes ?? input.text);
const patientEmail = str(input.patient_email).toLowerCase();
const preferredDate = str(input.preferred_date);

const missingFields = [];
const invalidFields = [];
const aliases = ['clinical_text', 'clinical_notes', 'text'].filter(k => input[k] !== undefined);
if (aliases.some(k => str(input[k]) !== clinicalText)) invalidFields.push('conflicting clinical text fields');
if (input.screening_complete !== undefined && typeof input.screening_complete !== 'boolean') invalidFields.push('screening_complete (use a JSON boolean)');
if (!caseId) missingFields.push("case_id");
if (!clinicalText) missingFields.push("clinical_text");
if (!patientEmail) missingFields.push("patient_email");
else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(patientEmail)) invalidFields.push("patient_email");
if (preferredDate && !/^\d{4}-\d{2}-\d{2}$/.test(preferredDate)) invalidFields.push("preferred_date (use YYYY-MM-DD)");

const valid = missingFields.length === 0 && invalidFields.length === 0;

return [{
  json: {
    case_id: caseId,
    // De-identified text: the only field sent to the matcher and the LLM.
    clinical_text: clinicalText,
    // Contact details: used only for the patient email, never sent to the matcher or LLM.
    patient_email: patientEmail,
    patient_first_name: str(input.patient_first_name),
    preferred_date: preferredDate || null,
    screening_complete: input.screening_complete === true,
    validation_status: valid ? "VALID" : "INVALID",
    missing_fields: missingFields,
    invalid_fields: invalidFields,
    received_at: new Date().toISOString(),
    config: CONFIG,
  },
}];

const intake = $('Validate Intake').first().json;
const gate = $input.first().json;

const response = {
  case_id: intake.case_id,
  safety_status: "EMERGENCY_ESCALATED",
  priority: "HIGH",
  booking_allowed: false,
  specialty: null,
  draft_booking: null,
  staff_approval_required: true,
  guidance: gate.guidance,
};

const queue_row = {
  case_id: intake.case_id,
  received_at: intake.received_at,
  route: "EMERGENCY_ESCALATED",
  priority: "EMERGENCY",
  reason: "Deterministic safety gate detected emergency indicators",
  specialty_suggestion: "", confidence: "", ci95_low: "", ci95_high: "",
  clinical_summary: "", clarification_questions: "",
  status: "OPEN", assigned_to: "", reviewer_decision: "", reviewed_at: "",
};

return [{
  json: {
    response,
    queue_row,
    staff_subject: `URGENT: emergency indicators in case ${intake.case_id}`,
    staff_message:
      `Case ${intake.case_id} matched emergency indicators in the deterministic safety gate.\n\n` +
      `No specialty matching or booking was run. The submitter was shown emergency guidance.\n` +
      `Follow up with the patient directly.\n\nReceived: ${intake.received_at}`,
  },
}];

const intake = $('Validate Intake').first().json;
const m = $input.first().json;
const s = $('Validate Staff Summary').first().json.output ?? {};
const threshold = intake.config.confidence_threshold;

const SUPPORTED = [
  "Cardiovascular / Pulmonary", "Orthopedic", "Gastroenterology", "Neurology",
  "Obstetrics / Gynecology", "Urology", "ENT - Otolaryngology", "Nephrology",
  "Dermatology", "Ophthalmology",
];

// Same rule as cardio_pulmonary_subroute() in the Milestone 2 notebook.
function cardioPulmonarySubroute(text) {
  const cardiac = /\b(cardiac|coronary|arrhythmia|heart failure|palpitations)\b/i.test(text);
  const pulmonary = /\b(pulmonary|asthma|COPD|wheez(?:e|ing)|lung)\b/i.test(text);
  if (cardiac === pulmonary) return null;
  return cardiac ? "Cardiology" : "Pulmonology";
}

const missing = Array.isArray(s.missing_information) ? s.missing_information : [];
let reviewReason = null;
let proposed = null;

const gate = $('Run Safety Gate').first().json;
if (intake.validation_status !== 'VALID' || intake.screening_complete !== true || gate.safety_status !== 'NONEMERGENCY_ELIGIBLE' || (m.safety_status !== undefined && m.safety_status !== 'NONEMERGENCY_ELIGIBLE')) {
  reviewReason = 'Intake or safety screening does not permit booking.';
} else if (!Number.isFinite(threshold) || threshold < 0 || threshold > 1) {
  reviewReason = 'Invalid confidence threshold configuration.';
} else if (typeof s.summary !== 'string' || !s.summary.trim() || !Array.isArray(s.missing_information)) {
  reviewReason = 'Summary output is missing or malformed.';
} else if (m.match_status !== "MATCHED") {
  reviewReason = m.reason || "The matcher did not return a specialty.";
} else if (!SUPPORTED.includes(m.specialty)) {
  reviewReason = `Unsupported specialty returned: ${m.specialty}`;
} else if (!Number.isFinite(m.confidence) || m.confidence < 0 || m.confidence > 1 || m.confidence < threshold) {
  reviewReason = `Low confidence: ${m.confidence} is below the ${threshold} threshold.`;
} else if (m.specialty === "Cardiovascular / Pulmonary") {
  proposed = cardioPulmonarySubroute(intake.clinical_text);
  reviewReason = "Combined Cardiovascular / Pulmonary label: staff must confirm Cardiology or Pulmonology before any draft.";
} else if (missing.length) {
  reviewReason = "The intake is missing information needed for a referral.";
}

return [{
  json: {
    ...m,
    booking_allowed: reviewReason === null,
    review_reason: reviewReason,
    proposed_scheduling_specialty: proposed,
    confidence_threshold: threshold,
    intake_summary: s.summary ?? null,
    missing_information: missing,
  },
}];

