const intake = $('Validate Intake').first().json;
const match = $('Apply Booking Policy').first().json;
const summary = match.intake_summary ?? null;
const cfg = intake.config;

// Earliest slot: next business day. Honor the preferred date if it is a weekday on or after that.
const now = DateTime.now().setZone(cfg.timezone);
let earliest = now.plus({ days: 1 }).startOf("day");
while (earliest.weekday > 5) earliest = earliest.plus({ days: 1 });

let slot = intake.preferred_date
  ? DateTime.fromISO(intake.preferred_date, { zone: cfg.timezone })
  : null;
const preferredHonored = Boolean(slot && slot.isValid && slot >= earliest && slot.weekday <= 5);
if (!preferredHonored) slot = earliest;

const [hour, minute] = cfg.default_appointment_time.split(":").map(Number);
slot = slot.set({ hour, minute, second: 0, millisecond: 0 });

const draft = {
  draft_id: `DRAFT-${intake.case_id}-${now.toFormat("yyyyLLddHHmmss")}`,
  status: "DRAFT_PENDING_STAFF_APPROVAL",
  specialty: match.specialty,
  proposed_start: slot.toISO(),
  proposed_end: slot.plus({ minutes: cfg.appointment_minutes }).toISO(),
  duration_minutes: cfg.appointment_minutes,
  timezone: cfg.timezone,
  preferred_date: intake.preferred_date,
  preferred_date_honored: preferredHonored,
  created_at: now.toISO(),
};

const response = {
  case_id: intake.case_id,
  safety_status: "NONEMERGENCY_ELIGIBLE",
  booking_allowed: true,
  specialty: match.specialty,
  confidence: match.confidence,
  confidence_interval: match.confidence_interval ?? null,
  model_run_id: match.model_run_id,
  staff_approval_required: true,
  draft_booking: draft,
  intake_summary: summary,
};

const when = slot.toFormat("cccc, LLLL d, yyyy 'at' h:mm a");
const name = intake.patient_first_name || "there";

const emailBody =
`Hello ${name},

Thank you for your referral to ${cfg.clinic_name}. We have drafted an appointment request with our ${match.specialty} team for ${when} (${cfg.timezone.replace("_", " ")}).

This appointment is not confirmed yet. A member of our staff will review the request and contact you to confirm it or offer another time.

If your symptoms get worse, or you have chest pain, trouble breathing, sudden weakness, or other severe symptoms, call 911 or go to the nearest emergency department. Do not wait for this appointment.

Reference number: ${intake.case_id}

${cfg.clinic_name}`;

const ci = match.confidence_interval;
const calendarDescription = [
  "DRAFT created by Sentient AI. Requires staff approval before it is confirmed.",
  "",
  `Case: ${intake.case_id}`,
  `Specialty: ${match.specialty}`,
  `Confidence (MLP 64, ${match.model_run_id}): ${match.confidence} (threshold ${match.confidence_threshold})`,
  ci ? `Validation accuracy in band ${ci.band}: ${ci.validation_accuracy}, 95% CI ${ci.ci95_low}-${ci.ci95_high} (n=${ci.n_validation_cases})` : "",
  "",
  "Intake summary (de-identified):",
  summary ?? "(not available)",
].join("\n");

return [{
  json: {
    response,
    calendar_title: `[DRAFT - needs staff approval] ${match.specialty} referral - case ${intake.case_id}`,
    calendar_description: calendarDescription,
    patient_email: intake.patient_email,
    email_subject: `Your ${cfg.clinic_name} appointment request`,
    email_body: emailBody,
  },
}];

const draft = $('Draft Appointment').first().json;
const emailSent = !$input.first().json.error;
const ev = $('Create Draft in Google Calendar').first().json;
const r = { ...draft.response, patient_email_sent: emailSent };
r.draft_booking = { ...r.draft_booking, calendar_event_id: ev.id ?? null, calendar_link: ev.htmlLink ?? null };
const d = r.draft_booking;

const staffMessage =
`Draft appointment ${d.draft_id} needs staff approval.

Case: ${r.case_id}
Specialty: ${r.specialty} (confidence ${r.confidence}, model ${r.model_run_id})
Proposed start: ${d.proposed_start} (${d.timezone})
Calendar draft: ${d.calendar_link ?? "(link unavailable)"}
Preferred date honored: ${d.preferred_date_honored ? "yes" : "no"}
Patient email sent: ${emailSent ? "yes" : "NO - contact the patient directly"}

Intake summary (de-identified):
${r.intake_summary ?? "(not available)"}`;

return [{ json: { response: r, staff_subject: `Approve draft appointment: case ${r.case_id}`, staff_message: staffMessage } }];

// Every non-emergency path that cannot be booked automatically ends here.
// It never substitutes a default specialty.
const intake = $('Validate Intake').first().json;
const j = $input.first().json;
const tryNode = (name) => { try { return $(name).first().json; } catch (e) { return null; } };

let reason;
let questions = [];
if (j.error) {
  const msg = typeof j.error === "string" ? j.error : (j.error.message || "");
  reason = `A workflow step failed, so the case was not routed automatically. ${msg}`.trim();
} else if (j.review_reason) {
  reason = j.review_reason;
  questions = j.missing_information ?? [];
} else if (j.safety_status === "REVIEW_REQUIRED") {
  reason = j.guidance || "Screening requires review.";
} else {
  reason = "Unrecognized result; routed to staff review.";
}

// Pull the Claude summary and model output if those steps ran.
const summary = tryNode('Validate Staff Summary')?.output?.summary ?? null;
const policy = j.specialty ? j : tryNode('Apply Booking Policy');
const suggestion = policy && policy.specialty
  ? { specialty: policy.specialty, confidence: policy.confidence ?? null,
      confidence_interval: policy.confidence_interval ?? null,
      proposed_scheduling_specialty: policy.proposed_scheduling_specialty ?? null,
      top_candidates: policy.top_candidates ?? [] }
  : null;

const response = {
  case_id: intake.case_id,
  safety_status: "REVIEW_REQUIRED",
  booking_allowed: false,
  specialty: null,
  draft_booking: null,
  staff_approval_required: true,
  review_reason: reason,
  clarification_questions: questions,
  guidance: "This referral has been sent to clinical staff for manual review.",
};

let staffMessage = `Case ${intake.case_id} needs manual review.\n\nReason: ${reason}\n`;
if (questions.length) staffMessage += `\nClarification needed:\n- ${questions.join("\n- ")}\n`;
if (suggestion) {
  staffMessage += `\nModel suggestion (not booked): ${suggestion.specialty}` +
    (suggestion.confidence !== null ? ` (confidence ${suggestion.confidence})` : "") +
    (suggestion.proposed_scheduling_specialty ? `; keyword sub-route: ${suggestion.proposed_scheduling_specialty}` : "") + "\n";
}
if (summary) staffMessage += `\nIntake summary (de-identified):\n${summary}\n`;
staffMessage += `\nReceived: ${intake.received_at}`;

const ci = suggestion?.confidence_interval;
const queue_row = {
  case_id: intake.case_id,
  received_at: intake.received_at,
  route: "CLINICAL_REVIEW",
  priority: j.error ? "HIGH" : (j.safety_status === "REVIEW_REQUIRED" ? "HIGH" : "ROUTINE"),
  reason,
  specialty_suggestion: suggestion?.specialty ?? "",
  confidence: suggestion?.confidence ?? "",
  ci95_low: ci?.ci95_low ?? "",
  ci95_high: ci?.ci95_high ?? "",
  clinical_summary: summary ?? "",
  clarification_questions: questions.join("; "),
  status: "OPEN",
  assigned_to: "",
  reviewer_decision: "",
  reviewed_at: "",
};

return [{ json: { response, staff_subject: `Review needed: case ${intake.case_id}`, staff_message: staffMessage, queue_row } }];

const raw = $input.first().json;
let s = raw.output ?? raw.text;
if (typeof s === 'string') { try { s = JSON.parse(s); } catch (_) { s = null; } }
const valid = s && typeof s.summary === 'string' && s.summary.trim().length > 0
  && Array.isArray(s.missing_information) && s.missing_information.every(q => typeof q === 'string' && q.trim().length > 0);
const questions = valid ? s.missing_information : [];
return [{json: {
  output: valid ? s : null,
  summary_ready: Boolean(valid && questions.length === 0),
  missing_information: questions,
  review_reason: !valid ? 'Summary output is missing or malformed.' : questions.length ? 'Clarification is required before specialty matching.' : null
}}];
